1|//! Deterministic seeded random streams for engine simulation.
2|
3|use std::fmt;
4|
5|use serde::{Deserialize, Deserializer, Serialize, Serializer};
6|
7|const STREAM_DOMAIN: u64 = 0x554e_4349_5652_4e47;
8|const SPLITMIX_INCREMENT: u64 = 0x9e37_79b9_7f4a_7c15;
9|
10|/// Identifies an independent deterministic random stream.
11|///
12|/// Subsystems should declare explicit numeric constants and must not renumber or reuse an
13|/// identifier after it contributes to persisted or observable behavior.
14|#[derive(Clone, Copy, Debug, Eq, Hash, Ord, PartialEq, PartialOrd)]
15|#[repr(transparent)]
16|pub struct RngStreamId(u64);
17|
18|impl RngStreamId {
19|    /// Creates a stream identifier from its stable numeric representation.
20|    #[must_use]
21|    pub const fn new(value: u64) -> Self {
22|        Self(value)
23|    }
24|
25|    /// Returns the stable numeric representation.
26|    #[must_use]
27|    pub const fn get(self) -> u64 {
28|        self.0
29|    }
30|}
31|
32|impl From<u64> for RngStreamId {
33|    fn from(value: u64) -> Self {
34|        Self::new(value)
35|    }
36|}
37|
38|impl From<RngStreamId> for u64 {
39|    fn from(value: RngStreamId) -> Self {
40|        value.get()
41|    }
42|}
43|
44|impl fmt::Display for RngStreamId {
45|    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
46|        self.0.fmt(formatter)
47|    }
48|}
49|
50|impl Serialize for RngStreamId {
51|    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
52|    where
53|        S: Serializer,
54|    {
55|        serializer.collect_str(&format_args!("{:016x}", self.0))
56|    }
57|}
58|
59|impl<'de> Deserialize<'de> for RngStreamId {
60|    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
61|    where
62|        D: Deserializer<'de>,
63|    {
64|        let value = String::deserialize(deserializer)?;
65|        if value.len() != 16 || !value.bytes().all(|byte| byte.is_ascii_hexdigit()) {
66|            return Err(serde::de::Error::custom(
67|                "RNG stream identifier must contain exactly 16 hexadecimal digits",
68|            ));
69|        }
70|
71|        u64::from_str_radix(&value, 16)
72|            .map(Self::new)
73|            .map_err(serde::de::Error::custom)
74|    }
75|}
76|
77|/// A reproducible `SplitMix64` stream derived from a root seed and stable stream identifier.
78|#[derive(Clone, Debug)]
79|pub struct SeededRng {
80|    state: u64,
81|}
82|
83|impl SeededRng {
84|    /// Creates a stream at the beginning of the sequence for `seed` and `stream_id`.
85|    #[must_use]
86|    pub const fn new(seed: i64, stream_id: RngStreamId) -> Self {
87|        let stream_state = mix64(stream_id.get() ^ STREAM_DOMAIN);
88|        let state = mix64(seed.cast_unsigned() ^ stream_state);
89|        Self { state }
90|    }
91|
92|    /// Advances the stream and returns the next unsigned 64-bit value.
93|    pub fn next_u64(&mut self) -> u64 {
94|        self.state = self.state.wrapping_add(SPLITMIX_INCREMENT);
95|        mix64(self.state)
96|    }
97|}
98|
99|const fn mix64(mut value: u64) -> u64 {
100|    value = (value ^ (value >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
101|    value = (value ^ (value >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
102|    value ^ (value >> 31)
103|}

