1|//! Contract tests for strongly typed entity identifiers.
2|
3|use std::{
4|    fmt::{Debug, Display},
5|    str::FromStr,
6|};
7|
8|use proptest::prelude::*;
9|use serde::{Serialize, de::DeserializeOwned};
10|use unciv_engine::id::{CityId, CivilizationId, GameId, UnitId};
11|use uuid::Uuid;
12|
13|fn assert_id_round_trip<Id>(raw: u32)
14|where
15|    Id: Copy + Debug + Display + Eq + From<u32> + Into<u32> + Serialize + DeserializeOwned,
16|{
17|    let id = Id::from(raw);
18|
19|    assert_eq!(id.into(), raw);
20|    assert_eq!(id.to_string(), raw.to_string());
21|
22|    let encoded = serde_json::to_string(&id).expect("serialize entity ID");
23|    assert_eq!(encoded, raw.to_string());
24|
25|    let decoded = serde_json::from_str::<Id>(&encoded).expect("deserialize entity ID");
26|    assert_eq!(decoded, id);
27|}
28|
29|proptest! {
30|    #[test]
31|    fn entity_ids_round_trip_for_arbitrary_raw_values(raw in any::<u32>()) {
32|        assert_id_round_trip::<CivilizationId>(raw);
33|        assert_id_round_trip::<CityId>(raw);
34|        assert_id_round_trip::<UnitId>(raw);
35|    }
36|
37|    #[test]
38|    fn game_ids_round_trip_for_arbitrary_uuid_bytes(bytes in any::<[u8; 16]>()) {
39|        let uuid = Uuid::from_bytes(bytes);
40|        let id = GameId::new(uuid);
41|
42|        assert_eq!(id.get(), uuid);
43|        assert_eq!(Uuid::from(id), uuid);
44|        assert_eq!(GameId::from_str(&id.to_string()).expect("parse game ID"), id);
45|
46|        let encoded = serde_json::to_string(&id).expect("serialize game ID");
47|        assert_eq!(encoded, format!("\"{uuid}\""));
48|
49|        let decoded = serde_json::from_str::<GameId>(&encoded).expect("deserialize game ID");
50|        assert_eq!(decoded, id);
51|    }
52|}
53|
54|#[test]
55|fn entity_ids_round_trip_at_raw_value_boundaries() {
56|    for raw in [u32::MIN, 1, u32::MAX] {
57|        assert_id_round_trip::<CivilizationId>(raw);
58|        assert_id_round_trip::<CityId>(raw);
59|        assert_id_round_trip::<UnitId>(raw);
60|    }
61|}

