1|//! Contract tests for deterministic seeded random streams.
2|
3|use unciv_engine::random::{RngStreamId, SeededRng};
4|
5|const STREAM: RngStreamId = RngStreamId::new(0x0123_4567_89ab_cdef);
6|
7|#[test]
8|fn stream_id_preserves_its_raw_value() {
9|    assert_eq!(STREAM.get(), 0x0123_4567_89ab_cdef);
10|    assert_eq!(u64::from(STREAM), 0x0123_4567_89ab_cdef);
11|    assert_eq!(STREAM.to_string(), "81985529216486895");
12|}
13|
14|#[test]
15|fn stream_id_serializes_as_fixed_width_hexadecimal() {
16|    let encoded = serde_json::to_string(&STREAM).expect("serialize RNG stream identifier");
17|    assert_eq!(encoded, r#""0123456789abcdef""#);
18|    assert_eq!(
19|        serde_json::from_str::<RngStreamId>(&encoded).expect("deserialize RNG stream identifier"),
20|        STREAM,
21|    );
22|
23|    let maximum = RngStreamId::new(u64::MAX);
24|    let maximum_encoded =
25|        serde_json::to_string(&maximum).expect("serialize maximum RNG stream identifier");
26|    assert_eq!(maximum_encoded, r#""ffffffffffffffff""#);
27|    assert_eq!(
28|        serde_json::from_str::<RngStreamId>(&maximum_encoded)
29|            .expect("deserialize maximum RNG stream identifier"),
30|        maximum,
31|    );
32|}
33|
34|#[test]
35|fn stream_id_rejects_malformed_serialized_values() {
36|    for invalid in [
37|        "7",
38|        r#""7""#,
39|        r#""0123456789abcde""#,
40|        r#""0123456789abcdef0""#,
41|        r#""0123456789abcdeg""#,
42|    ] {
43|        assert!(serde_json::from_str::<RngStreamId>(invalid).is_err());
44|    }
45|}
46|
47|#[test]
48|fn seeded_stream_matches_the_golden_sequence() {
49|    let mut rng = SeededRng::new(-42, STREAM);
50|
51|    let sequence = [
52|        rng.next_u64(),
53|        rng.next_u64(),
54|        rng.next_u64(),
55|        rng.next_u64(),
56|        rng.next_u64(),
57|    ];
58|
59|    assert_eq!(
60|        sequence,
61|        [
62|            0xecc2_ae24_7554_c283,
63|            0xf081_9020_4e02_12a0,
64|            0x0f16_d892_34f4_6253,
65|            0x360b_c19f_0f0f_7207,
66|            0xdbd9_d245_a610_0c36,
67|        ],
68|    );
69|}
70|
71|#[test]
72|fn reconstructing_a_stream_reproduces_its_sequence() {
73|    let mut first = SeededRng::new(i64::MIN, STREAM);
74|    let mut second = SeededRng::new(i64::MIN, STREAM);
75|
76|    for _ in 0..16 {
77|        assert_eq!(first.next_u64(), second.next_u64());
78|    }
79|}
80|
81|#[test]
82|fn distinct_stream_ids_produce_distinct_sequences() {
83|    let mut first = SeededRng::new(42, RngStreamId::new(7));
84|    let mut second = SeededRng::new(42, RngStreamId::new(8));
85|
86|    let first_prefix = [first.next_u64(), first.next_u64(), first.next_u64()];
87|    let second_prefix = [second.next_u64(), second.next_u64(), second.next_u64()];
88|
89|    assert_ne!(first_prefix, second_prefix);
90|}

