2|
3|use proptest::prelude::*;
4|use unciv_engine::hex::HexCoord;
5|
6|#[test]
7|fn components_retain_signed_unciv_coordinates() {
8|    let coordinate = HexCoord::new(-7, 11);
9|
10|    assert_eq!(coordinate.x(), -7);
11|    assert_eq!(coordinate.y(), 11);
12|}
13|
14|#[test]
15|fn neighbors_follow_unciv_clockwise_order() {
16|    let origin = HexCoord::new(3, -2);
17|
18|    assert_eq!(
19|        origin.neighbors(),
20|        [
21|            HexCoord::new(4, -1),
22|            HexCoord::new(3, -1),
23|            HexCoord::new(2, -2),
24|            HexCoord::new(2, -3),
25|            HexCoord::new(3, -3),
26|            HexCoord::new(4, -2),
27|        ]
28|    );
29|}
30|
31|#[test]
32|fn neighbors_reject_every_unrepresentable_coordinate_boundary() {
33|    for coordinate in [
34|        HexCoord::new(i32::MAX, 0),
