//!
//! Every successful command increments the revision exactly once. Clients capture the current
//! revision and send it as the expected revision with their next command; the engine rejects
//! stale commands without mutating state. The revision also identifies the exact state version
//! for persistence, multiplayer conflict detection, and diagnostic bundles.

use std::{fmt, str::FromStr};

use serde::{Deserialize, Deserializer, Serialize, Serializer, de::Visitor};

/// Error returned when a game revision cannot be incremented further.
///
/// Revisions use the full `u64` range, so this error is unreachable in normal gameplay, but the
/// engine must fail explicitly rather than wrap around to a reused revision.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq, thiserror::Error)]
#[error("game revision overflow")]
pub struct RevisionOverflow;

/// Alias for [`RevisionOverflow`] using the `*Error` naming convention.
pub type RevisionOverflowError = RevisionOverflow;

/// Alias for [`RevisionOverflow`] for callers that expect a generic overflow name.
pub type OverflowError = RevisionOverflow;

/// Alias for [`RevisionOverflow`] for callers that expect a revision-scoped error name.
pub type RevisionError = RevisionOverflow;

/// A monotonic counter identifying a specific version of game state.
///
/// The initial revision is `0`. Each successful command creates the next revision (`1`, `2`, …).
/// The type is a transparent `u64` newtype so it serializes as a plain JSON number, matches the
/// JavaScript boundary as a safe integer for realistic game lengths, and prevents accidental
/// mixing with unrelated counters.
#[derive(Clone, Copy, Debug, Default, Eq, Hash, Ord, PartialEq, PartialOrd)]
#[repr(transparent)]
pub struct GameRevision(u64);

/// Alias for [`GameRevision`].
pub type Revision = GameRevision;

/// Alias for [`GameRevision`] emphasizing its role as state version.
pub type StateRevision = GameRevision;

/// Alias for [`GameRevision`] emphasizing its role as game-state version.
pub type GameStateRevision = GameRevision;

impl GameRevision {
    /// The revision of a newly created game before any command has been applied.
    pub const INITIAL: Self = Self::new(0);

    /// Alias for [`Self::INITIAL`].
    pub const ZERO: Self = Self::new(0);

    /// The smallest representable revision, which is the initial revision.
    pub const MIN: Self = Self::new(u64::MIN);

    /// The largest representable revision.
    pub const MAX: Self = Self::new(u64::MAX);

    /// Creates a revision from its stable numeric representation.
    #[must_use]
    pub const fn new(value: u64) -> Self {
        Self(value)
    }

    /// Returns the stable numeric representation.
    #[must_use]
    pub const fn get(self) -> u64 {
        self.0
    }

    /// Returns `true` if this is the initial revision.
    #[must_use]
    pub const fn is_initial(self) -> bool {
        self.0 == 0
    }

    /// Returns the next revision, or an error if this is the maximum revision.
    ///
    /// # Errors
    ///
    /// Returns [`RevisionOverflow`] when `self` is [`Self::MAX`].
    pub fn next(self) -> Result<Self, RevisionOverflow> {
        self.checked_next().ok_or(RevisionOverflow)
    }

    /// Returns the next revision, or `None` if this is the maximum revision.
    #[must_use]
    pub const fn checked_next(self) -> Option<Self> {
        match self.0.checked_add(1) {
            Some(value) => Some(Self::new(value)),
            None => None,
        }
    }

    /// Alias for [`Self::next`].
    ///
    /// # Errors
    ///
    /// Returns [`RevisionOverflow`] when `self` is [`Self::MAX`].
    pub fn try_next(self) -> Result<Self, RevisionOverflow> {
        self.next()
    }

    /// Alias for [`Self::checked_next`].
    #[must_use]
    pub const fn checked_increment(self) -> Option<Self> {
        self.checked_next()
    }

    /// Alias for [`Self::next`].
    ///
    /// # Errors
    ///
    /// Returns [`RevisionOverflow`] when `self` is [`Self::MAX`].
    pub fn increment_once(self) -> Result<Self, RevisionOverflow> {
        self.next()
    }

    /// Alias for [`Self::next`] using the `next_revision` naming.
    ///
    /// # Errors
    ///
    /// Returns [`RevisionOverflow`] when `self` is [`Self::MAX`].
    pub fn next_revision(self) -> Result<Self, RevisionOverflow> {
        self.next()
    }

    /// Increments this revision in place, or returns an error on overflow.
    ///
    /// On error the revision is left unchanged.
    ///
    /// # Errors
    ///
    /// Returns [`RevisionOverflow`] when `self` is [`Self::MAX`].
    pub fn increment(&mut self) -> Result<(), RevisionOverflow> {
        let next = self.next()?;
        *self = next;
        Ok(())
    }

    /// Alias for [`Self::increment`].
    ///
    /// # Errors
    ///
    /// Returns [`RevisionOverflow`] when `self` is [`Self::MAX`].
    pub fn try_increment(&mut self) -> Result<(), RevisionOverflow> {
        self.increment()
    }

    /// Returns the next revision without mutating `self`.
    ///
    /// This is equivalent to [`Self::next`]; it exists for callers that prefer an explicit
    /// successor naming.
    ///
    /// # Errors
    ///
    /// Returns [`RevisionOverflow`] when `self` is [`Self::MAX`].
    pub fn successor(self) -> Result<Self, RevisionOverflow> {
        self.next()
    }

    /// Returns `true` if `expected` matches this revision.
    ///
    /// Command handlers use this to detect stale clients: the expected revision sent with a
    /// command must equal the current revision.
    #[must_use]
    pub const fn matches(self, expected: Self) -> bool {
        self.0 == expected.0
    }

    /// Returns `true` if `expected` is stale compared to this revision.
    #[must_use]
    pub const fn is_stale(self, expected: Self) -> bool {
        !self.matches(expected)
    }
}

impl From<u64> for GameRevision {
    fn from(value: u64) -> Self {
        Self::new(value)
    }
}

impl From<GameRevision> for u64 {
    fn from(value: GameRevision) -> Self {
        value.get()
    }
}

impl fmt::Display for GameRevision {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(formatter)
    }
}

impl FromStr for GameRevision {
    type Err = std::num::ParseIntError;

    fn from_str(value: &str) -> Result<Self, Self::Err> {
        value.parse::<u64>().map(Self::new)
    }
}

impl Serialize for GameRevision {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_u64(self.0)
    }
}

impl<'de> Deserialize<'de> for GameRevision {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        struct GameRevisionVisitor;

        impl Visitor<'_> for GameRevisionVisitor {
            type Value = GameRevision;

            fn expecting(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
                formatter.write_str("a game revision as an unsigned integer or numeric string")
            }

            fn visit_u64<E>(self, value: u64) -> Result<Self::Value, E>
            where
                E: serde::de::Error,
            {
                Ok(GameRevision::new(value))
            }

            fn visit_i64<E>(self, value: i64) -> Result<Self::Value, E>
            where
                E: serde::de::Error,
            {
                u64::try_from(value)
                    .map(GameRevision::new)
                    .map_err(|_| E::custom("game revision must be non-negative"))
            }

            fn visit_str<E>(self, value: &str) -> Result<Self::Value, E>
            where
                E: serde::de::Error,
            {
                value
                    .parse::<u64>()
                    .map(GameRevision::new)
                    .map_err(E::custom)
            }

            fn visit_string<E>(self, value: String) -> Result<Self::Value, E>
            where
                E: serde::de::Error,
            {
                self.visit_str(&value)
            }
        }

        deserializer.deserialize_any(GameRevisionVisitor)
    }
}
