14|/// Revisions use the full `u64` range, so this error is unreachable in normal gameplay, but the
15|/// engine must fail explicitly rather than wrap around to a reused revision.
16|#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq, thiserror::Error)]
17|#[error("game revision overflow")]
18|pub struct RevisionOverflow;
19|
20|/// Alias for [`RevisionOverflow`] using the `*Error` naming convention.
21|pub type RevisionOverflowError = RevisionOverflow;
22|
